B:  Checkpoints

  各学生がどのチェックポイントに移動するかを調べます。まず、全てのチェックポイント間のマンハッタン距離

 を計算します。多くのプログラミング言語では、絶対値を求める処理はライブラリで提供されています。次に、マ

 ンハッタン距離が最小となるチェックポイントの番号を求めていきます。これはマンハッタン距離の最小値とその

 チェックポイントの番号を管理する2 つの変数を用いて、ループで求めることが可能です。以上のことから、時間
 計算量はO(NM) となり、これは間に合います。


  C++のコード例



1 int main(void){

2     int N,M;

3     cin >> N >> M;


4

5     const int NMMAX=50;

6     int A[NMMAX],B[NMMAX],C[NMMAX],D[NMMAX];


7


                                                  1

 8     for(int i=0;i<N;++i){
 9         cin >> A[i] >> B[i];

10     }


11

12     for(int j=0;j<M;++j){

13         cin >> C[j] >> D[j];

14     }


15

16     for(int i=0;i<N;++i){

17         int min_dist=abs(A[i]-C[0])+abs(B[i]-D[0]),checkpoint=1;


18

19         for(int j=1;j<M;++j){

20             const int cur_dist=abs(A[i]-C[j])+abs(B[i]-D[j]);

21             if(min_dist>cur_dist){

22                 min_dist=cur_dist;

23                 checkpoint=j+1;

24             }

25         }


26

27         cout << checkpoint << endl;

28     }


29

30     return 0;

31 }
